import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000/admin/orders"; // ✅ update if needed

export default function AdminPayments() {
  const [orders, setOrders] = useState([]);
  const [search, setSearch] = useState("");

  const today = new Date().toISOString().split("T")[0];
  const yesterday = new Date(Date.now() - 86400000)
    .toISOString()
    .split("T")[0];

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const token = localStorage.getItem("adminToken");

        const res = await axios.get(API_URL, {
          headers: { Authorization: `Bearer ${token}` },
        });

        setOrders(
          res.data.sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
        );
      } catch (error) {
        console.error("Admin Orders Fetch Error:", error);
      }
    };

    fetchOrders();
  }, []);

  const filteredOrders = orders.filter((item) => {
    const orderDate = item.created_at.split("T")[0];
    return (
      item.customer_name.toLowerCase().includes(search.toLowerCase()) ||
      String(item.order_id).includes(search) ||
      orderDate.includes(search) ||
      item.customer_address.toLowerCase().includes(search.toLowerCase())
    );
  });

  const todayTotal = orders
    .filter((o) => o.created_at.split("T")[0] === today)
    .reduce((sum, o) => sum + Number(o.amount), 0);

  const yesterdayTotal = orders
    .filter((o) => o.created_at.split("T")[0] === yesterday)
    .reduce((sum, o) => sum + Number(o.amount), 0);

  return (
    <div style={container}>
      <h2 style={header}>📊 Admin Payments Dashboard</h2>

      {/* Summary Cards */}
      <div style={summaryRow}>
        <div style={{ ...card, background: "#005C78" }}>
          <p style={cardTitle}>Today’s Revenue</p>
          <h2 style={cardAmount}>₹{todayTotal.toLocaleString()}</h2>
        </div>
        <div style={{ ...card, background: "#7E30E1" }}>
          <p style={cardTitle}>Yesterday’s Revenue</p>
          <h2 style={cardAmount}>₹{yesterdayTotal.toLocaleString()}</h2>
        </div>
      </div>

      {/* Search */}
      <input
        type="text"
        value={search}
        placeholder="Search by name, order id, date, address..."
        onChange={(e) => setSearch(e.target.value)}
        style={searchInput}
      />

      {/* Table */}
      <table style={table}>
        <thead style={thead}>
          <tr>
            <th style={th}>Order ID</th>
            <th style={th}>Customer</th>
            <th style={th}>Amount</th>
            <th style={th}>Date</th>
            <th style={th}>Address</th>
          </tr>
        </thead>
        <tbody>
          {filteredOrders.length > 0 ? (
            filteredOrders.map((order) => (
              <tr key={order.order_id} style={row}>
                <td style={td}>{order.order_id}</td>
                <td style={td}>{order.customer_name}</td>
                <td style={{ ...td, fontWeight: "bold", color: "#008000" }}>
                  ₹{order.amount}
                </td>
                <td style={td}>{order.created_at.split("T")[0]}</td>
                <td style={td}>{order.customer_address}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" style={{ ...td, textAlign: "center" }}>
                No results found
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

/* ========== Inline CSS ========== */

const container = {
  width: "95%",
  margin: "auto",
  padding: "20px",
  fontFamily: "Poppins, sans-serif",
};

const header = {
  background: "#202A44",
  color: "white",
  padding: "12px",
  borderRadius: "8px",
};

const summaryRow = {
  display: "flex",
  gap: "20px",
  marginTop: "20px",
  flexWrap: "wrap",
};

const card = {
  flex: "1",
  padding: "18px",
  borderRadius: "14px",
  color: "white",
  minWidth: "250px",
  boxShadow: "0 3px 10px rgba(0,0,0,0.2)",
};

const cardTitle = {
  fontSize: "14px",
  opacity: "0.9",
};

const cardAmount = {
  fontSize: "28px",
  margin: "0",
};

const searchInput = {
  marginTop: "20px",
  padding: "12px",
  width: "100%",
  border: "2px solid #202A44",
  borderRadius: "6px",
};

const table = {
  width: "100%",
  marginTop: "25px",
  borderCollapse: "collapse",
  background: "white",
  borderRadius: "10px",
  overflow: "hidden",
};

const thead = {
  background: "#202A44",
  color: "white",
};

const th = {
  padding: "12px",
  borderBottom: "2px solid #333",
};

const td = {
  padding: "10px",
  borderBottom: "1px solid #ddd",
  textAlign: "center",
};

const row = {
  background: "white",
};
